import math
    import random
    import time

    LANGUAGE_WRAPPER = 'You place a single base-10 digit (0–9) in each cell of a 2×{n_cols} grid. Reading each row left-to-right forms two integers whose sum is {row_target}. Reading each column top-to-bottom forms {n_cols} two-digit integers whose total sum is {col_target}. Additionally, the leftmost top and bottom digits must be nonzero, the sum of the digits in the top row is {top_sum}, and when adding the two row-numbers using the standard right-to-left addition algorithm, exactly {carries_required} carries occur. How many valid fillings of the grid exist?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Try random instances first, ensure nontrivial carries and feasibility
def build_random_instance():
    n = rng.randint(3, 4)
    # pick row_target digits (not all 9s to avoid trivial structure)
    r_digits = [rng.randint(0, 9) for _ in range(n)]
    if all(d == 9 for d in r_digits):
        return None
    pairs = [None] * n  # (a,b) digits per column from left to right
    carry = 0
    carry_count = 0
    # build from rightmost to leftmost
    for pos in range(n - 1, -1, -1):
        d = r_digits[pos]
        allowed = []
        s0 = d - carry
        if 0 <= s0 <= 18:
            a_min = max(0, s0 - 9)
            a_max = min(9, s0)
            for a in range(a_min, a_max + 1):
                b = s0 - a
                allowed.append((a, b, 0))
        s1 = d - carry + 10
        if 0 <= s1 <= 18 and pos != 0:  # no final carry out at leftmost
            a_min = max(0, s1 - 9)
            a_max = min(9, s1)
            for a in range(a_min, a_max + 1):
                b = s1 - a
                allowed.append((a, b, 1))
        if pos == 0:
            allowed = [(a, b, c) for (a, b, c) in allowed if a >= 1 and b >= 1 and c == 0]
        if not allowed:
            return None
        a, b, new_carry = rng.choice(allowed)
        pairs[pos] = (a, b)
        carry_count += new_carry
        carry = new_carry
    if carry != 0:
        return None
    top_sum = sum(a for a, b in pairs)
    # avoid extreme top_sum values
    if top_sum <= 1 or top_sum >= 9 * n - 1:
        return None
    if carry_count == 0 or carry_count > n - 1:
        return None
    col_target = sum(10 * a + b for a, b in pairs)
    # assemble row_target from digits
    row_target = 0
    for i in range(n):
        row_target = row_target * 10 + r_digits[i]
    return {
        'n_cols': n,
        'row_target': row_target,
        'col_target': col_target,
        'carries_required': carry_count,
        'top_sum': top_sum
    }

for _ in range(200):
    inst = build_random_instance()
    if inst is not None:
        return inst

# Fallback deterministic instance ensuring at least one carry and feasibility
# Construct n=3, row_target digits [5,8,4] with one carry in the middle
n = 3
r_digits = [5, 8, 4]
# Build specific pairs from rightmost to leftmost:
# pos=2 (rightmost, d=4): choose a+b=4 -> (2,2), carry=0
# pos=1 (d=8): choose a+b=18 -> (9,9), carry=1
# pos=0 (d=5, carry_in=1): a+b=4 -> (1,3), carry_out=0, with nonzero leftmost digits
pairs = [(1, 3), (9, 9), (2, 2)]  # left-to-right order
top_sum = sum(a for a, b in pairs)
col_target = sum(10 * a + b for a, b in pairs)
row_target = 0
for d in r_digits:
    row_target = row_target * 10 + d
carries_required = 1
return {
    'n_cols': n,
    'row_target': row_target,
    'col_target': col_target,
    'carries_required': carries_required,
    'top_sum': top_sum
}

    def verifier(assign):
# Validate presence and types
required = ['n_cols', 'row_target', 'col_target', 'carries_required', 'top_sum']
for k in required:
    if k not in assign:
        # missing key
        return (False, None)
n = assign['n_cols']
R = assign['row_target']
K = assign['col_target']
Creq = assign['carries_required']
Tsum = assign['top_sum']
if not (isinstance(n, int) and isinstance(R, int) and isinstance(K, int) and isinstance(Creq, int) and isinstance(Tsum, int)):
    return (False, None)
if not (3 <= n <= 4):
    # enforce manageable difficulty
    return (False, None)
if not (0 <= R < 10**n):
    # ensure no final carry in the target; R must be n-digit (leading zeros allowed)
    return (False, None)
# parse R into n digits left-to-right
rstr = str(R).zfill(n)
r_digits = [int(ch) for ch in rstr]
# disallow trivial all-9s which collapses the carry structure
if all(d == 9 for d in r_digits):
    return (False, None)
if not (1 <= Creq <= n - 1):
    # carries count must be nontrivial and cannot exceed n-1 (final carry must be 0)
    return (False, None)
if not (1 <= Tsum <= 9 * n - 1):
    return (False, None)
# The maximum column-sum is 99*n; minimum is 0*n; K must be in range
if not (0 <= K <= 99 * n):
    return (False, None)
# Dynamic programming over columns from rightmost to leftmost
# State: carry_in in {0,1}; accumulated column sum s_col; accumulated top-row digit sum s_top; number of carries used used_c
from collections import defaultdict

# dp[carry] is dict mapping (s_col, s_top, used_c) -> count
dp = [{}, {}]
dp[0][(0, 0, 0)] = 1

# iterate positions from right to left
for pos in range(n - 1, -1, -1):
    new_dp = [{}, {}]
    d = r_digits[pos]
    for carry_in in (0, 1):
        for (s_col, s_top, used_c), cnt in dp[carry_in].items():
            # generate allowed pairs given carry_in and target digit d
            # two possible sums: s0 = d - carry_in (carry_out=0) and s1 = d - carry_in + 10 (carry_out=1)
            candidates = []
            s0 = d - carry_in
            if 0 <= s0 <= 18:
                a_min = max(0, s0 - 9)
                a_max = min(9, s0)
                for a in range(a_min, a_max + 1):
                    b = s0 - a
                    candidates.append((a, b, 0))
            s1 = d - carry_in + 10
            # No final carry at leftmost column; enforce carry_out=0 for pos==0
            if 0 <= s1 <= 18 and pos != 0:
                a_min = max(0, s1 - 9)
                a_max = min(9, s1)
                for a in range(a_min, a_max + 1):
                    b = s1 - a
                    candidates.append((a, b, 1))
            for (a, b, c_out) in candidates:
                # enforce leftmost nonzero digits
                if pos == 0:
                    if not (a >= 1 and b >= 1 and c_out == 0):
                        continue
                # update sums and carry count
                ns_col = s_col + 10 * a + b
                ns_top = s_top + a
                n_used = used_c + (1 if c_out == 1 else 0)
                # prune exceeding targets
                if ns_col > K or ns_top > Tsum or n_used > Creq:
                    continue
                bucket = new_dp[c_out]
                key = (ns_col, ns_top, n_used)
                bucket[key] = bucket.get(key, 0) + cnt
    dp = new_dp

# After processing all columns, final carry must be 0, sums must match targets, and carries count equal Creq
ans = dp[0].get((K, Tsum, Creq), 0)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

